#include "stdafx.h"#include "SafetyManager.h"int g_chVer = 0x3500000B;KSafetyManager::KSafetyManager(): m_Ready( FALSE ){}int KSafetyManager::Initialize( LPCSTR pszPrj ){  OutputDebugString( "KSafetyManager::Init " );  OutputDebugString( pszPrj );  OutputDebugString( " ...\n" );  DWORD s = GetTickCount();  e_RestResult res = RestoryData( pszPrj );  switch( res )  {  case err_DatVerGreaterSrcVer:    {      if( IDYES!=MessageBox( NULL, "Использовать текущую версию будете на свой страх и риск.\nПродолжить?"                                 , "Устаревшая версия SafetyManager. Обновите SM.", MB_TOPMOST|MB_YESNO|MB_ICONWARNING|MB_DEFBUTTON2) )      {        exit( 1 );      }    }  case err_WrongKey:  case err_WrongVer:  case err_CantOpen:    ReadProject( pszPrj );    if( err_Ok != RestoryData( pszPrj ) )      return 2;    break;  default:  case err_CommonErr:    return 1;  case err_Ok:    break;  }  DWORD d = GetTickCount() - s;  char szDebug[64];  sprintf_s( szDebug, "время инициализации SafetyManager %d ms\n", d );  OutputDebugString( szDebug );  return 0;}void KSafetyManager::FscFileDraw( CMyFont& font, UINT nFile, UINT nSelect, bool bNumber ){  mFile.Draw( this, nFile, font, nSelect, bNumber );}